# Builds the compiler of one commit like the Windows CI does (Visual Studio generator, NASM, MSYS2 for FFmpeg) and installs it to a folder.
#   powershell -File benchmarks\build_windows.ps1 -Repo C:\claude-bench\repo -Commit <sha> -Out C:\claude-bench\scratch\x -Build C:\claude-bench\build
# The build folder is kept between commits, so the dependencies (ExternalContent) are only rebuilt when their sources change.
# Environment: BLITZLLVM_MSYS2 is the folder of MSYS2 (default C:\msys64), NASM must be on the PATH.
param([Parameter(Mandatory)] $Repo, [Parameter(Mandatory)] $Commit, [Parameter(Mandatory)] $Out, [Parameter(Mandatory)] $Build)
$ErrorActionPreference = "Stop"
$PSDefaultParameterValues["Out-File:Encoding"] = "utf8"  # Windows PowerShell writes the log as UTF-16 otherwise, which the Python side can not read.
if (-not $env:BLITZLLVM_MSYS2) { $env:BLITZLLVM_MSYS2 = "C:\msys64" }
Set-Location $Repo
git checkout -q --detach $Commit
# Old commits do not have every submodule, so only the ones that exist at this commit are fetched.
$wanted = "cmake/version", "cmake/externalcontent", "third_party/Vulkan-Headers", "third_party/SDL", "third_party/SDL_image", "third_party/SDL_mixer", "third_party/stb", "third_party/VulkanMemoryAllocator", "third_party/FFmpeg"
$present = @(git ls-files --stage | Where-Object { $_ -match '^160000' } | ForEach-Object { ($_ -split "\t")[1] })
$ErrorActionPreference = "Continue"
git submodule update --init --jobs 8 ($wanted | Where-Object { $present -contains $_ }) 2>&1 | Out-Null
$ErrorActionPreference = "Continue"  # cmake and git write progress to stderr, which Windows PowerShell would turn into an error; the exit codes are checked.
New-Item -ItemType Directory -Force $Out | Out-Null
$log = Join-Path $Out "build.log"
cmake -S . -B $Build -G "Visual Studio 18 2026" -A x64 -DBLITZLLVM_REQUIRE_NASM=ON *> $log
if ($LASTEXITCODE -ne 0 -and (Select-String -Path $log -Pattern "did not install the licenses" -Quiet)) {
    # The dependencies of the kept build folder were made without something that this commit adds (Opus, for example): build them again, once.
    Remove-Item -Recurse -Force (Join-Path $Build "ExternalContentFiles") -ErrorAction SilentlyContinue
    cmake -S . -B $Build -G "Visual Studio 18 2026" -A x64 -DBLITZLLVM_REQUIRE_NASM=ON *>> $log
}
if ($LASTEXITCODE -ne 0) { exit 2 }
cmake --build $Build --config Release *>> $log
if ($LASTEXITCODE -ne 0) { exit 2 }
cmake --install $Build --config Release --prefix $Out *>> $log
if ($LASTEXITCODE -ne 0) { exit 2 }
# The first commits only have the compiler and no install rule: its compiler.exe is what the later commits call blitzcc.exe.
if (-not (Get-ChildItem $Out -Recurse -Filter blitzcc.exe)) {
    $compiler = Get-ChildItem $Build -Recurse -Filter compiler.exe | Where-Object { $_.FullName -match "Release" } | Select-Object -First 1
    if ($compiler) { Copy-Item $compiler.FullName (Join-Path $Out "blitzcc.exe") }
}
